// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListContexts List kubeconfig contexts
	// (GET /api/contexts)
	ListContexts(w http.ResponseWriter, r *http.Request)
	// SelectContext Select a context and start watching it
	// (POST /api/contexts/{name}/select)
	SelectContext(w http.ResponseWriter, r *http.Request, name ContextNameParam)
	// CreateDeployment Create a Deployment (place a War Factory)
	// (POST /api/deployments)
	CreateDeployment(w http.ResponseWriter, r *http.Request)
	// DeleteDeployment Sell a structure (delete the Deployment; its pods follow)
	// (DELETE /api/deployments/{ns}/{name})
	DeleteDeployment(w http.ResponseWriter, r *http.Request, ns NamespaceParam, name NameParam)
	// SetDeploymentMapPos Persist the building's map tile as an annotation
	// (PATCH /api/deployments/{ns}/{name}/mappos)
	SetDeploymentMapPos(w http.ResponseWriter, r *http.Request, ns NamespaceParam, name NameParam)
	// ScaleDeployment Set replica count (build or sell units)
	// (PATCH /api/deployments/{ns}/{name}/scale)
	ScaleDeployment(w http.ResponseWriter, r *http.Request, ns NamespaceParam, name NameParam)
	// GetHealth Liveness and build info
	// (GET /api/healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// SearchHelmCharts Charts matching a query across cached repository indexes
	// (GET /api/helm/charts)
	SearchHelmCharts(w http.ResponseWriter, r *http.Request, params SearchHelmChartsParams)
	// GetHelmChartValues Default values.yaml of a chart
	// (GET /api/helm/charts/values)
	GetHelmChartValues(w http.ResponseWriter, r *http.Request, params GetHelmChartValuesParams)
	// ListHelmReleases Releases across all namespaces
	// (GET /api/helm/releases)
	ListHelmReleases(w http.ResponseWriter, r *http.Request)
	// InstallHelmRelease Install a chart (build a base expansion)
	// (POST /api/helm/releases)
	InstallHelmRelease(w http.ResponseWriter, r *http.Request)
	// UninstallHelmRelease Uninstall a release
	// (DELETE /api/helm/releases/{ns}/{name})
	UninstallHelmRelease(w http.ResponseWriter, r *http.Request, ns NamespaceParam, name NameParam)
	// GetHelmReleaseHistory Revisions of a release, newest last
	// (GET /api/helm/releases/{ns}/{name}/history)
	GetHelmReleaseHistory(w http.ResponseWriter, r *http.Request, ns NamespaceParam, name NameParam)
	// RollbackHelmRelease Roll a release back to a revision
	// (POST /api/helm/releases/{ns}/{name}/rollback)
	RollbackHelmRelease(w http.ResponseWriter, r *http.Request, ns NamespaceParam, name NameParam)
	// UpgradeHelmRelease Upgrade a release (new chart version and/or values)
	// (POST /api/helm/releases/{ns}/{name}/upgrade)
	UpgradeHelmRelease(w http.ResponseWriter, r *http.Request, ns NamespaceParam, name NameParam)
	// ListHelmRepos Chart repositories known to this machine (tech tree sources)
	// (GET /api/helm/repos)
	ListHelmRepos(w http.ResponseWriter, r *http.Request)
	// AddHelmRepo Add a chart repository and fetch its index
	// (POST /api/helm/repos)
	AddHelmRepo(w http.ResponseWriter, r *http.Request)
	// UpdateHelmRepos Refresh every repository index
	// (POST /api/helm/repos/update)
	UpdateHelmRepos(w http.ResponseWriter, r *http.Request)
	// CreateIngress Open a gate (create an Ingress)
	// (POST /api/ingresses)
	CreateIngress(w http.ResponseWriter, r *http.Request)
	// DeleteIngress Close a gate (delete the Ingress)
	// (DELETE /api/ingresses/{ns}/{name})
	DeleteIngress(w http.ResponseWriter, r *http.Request, ns NamespaceParam, name NameParam)
	// DeletePod Repair a unit (delete the pod so its ReplicaSet replaces it)
	// (DELETE /api/pods/{ns}/{name})
	DeletePod(w http.ResponseWriter, r *http.Request, ns NamespaceParam, name NameParam)
	// GetPodLogs Recent log lines of a pod's container (default container if unspecified)
	// (GET /api/pods/{ns}/{name}/logs)
	GetPodLogs(w http.ResponseWriter, r *http.Request, ns NamespaceParam, name NameParam, params GetPodLogsParams)
	// GetProgress Harbor Academy progress for this machine
	// (GET /api/progress)
	GetProgress(w http.ResponseWriter, r *http.Request)
	// PutLevelProgress Record a level result (best values are kept)
	// (PUT /api/progress/{level})
	PutLevelProgress(w http.ResponseWriter, r *http.Request, level string)
	// CreateService Light a lighthouse (create a Service)
	// (POST /api/services)
	CreateService(w http.ResponseWriter, r *http.Request)
	// DeleteService Put out a lighthouse (delete the Service)
	// (DELETE /api/services/{ns}/{name})
	DeleteService(w http.ResponseWriter, r *http.Request, ns NamespaceParam, name NameParam)
	// GetSnapshot Full cluster state for a fresh client
	// (GET /api/snapshot)
	GetSnapshot(w http.ResponseWriter, r *http.Request)
	// CreateJob Send out a fishing fleet (create a Job)
	// (POST /api/workloads/jobs)
	CreateJob(w http.ResponseWriter, r *http.Request)
	// CreateStatefulSet Build a tanker terminal (StatefulSet plus its headless Service)
	// (POST /api/workloads/statefulsets)
	CreateStatefulSet(w http.ResponseWriter, r *http.Request)
	// DeleteWorkload Delete a StatefulSet, DaemonSet or Job (and its pods)
	// (DELETE /api/workloads/{kind}/{ns}/{name})
	DeleteWorkload(w http.ResponseWriter, r *http.Request, kind DeleteWorkloadParamsKind, ns NamespaceParam, name NameParam)
	// SetWorkloadMapPos Persist a workload structure's map tile as an annotation
	// (PATCH /api/workloads/{kind}/{ns}/{name}/mappos)
	SetWorkloadMapPos(w http.ResponseWriter, r *http.Request, kind SetWorkloadMapPosParamsKind, ns NamespaceParam, name NameParam)
	// ScaleWorkload Set replicas on a StatefulSet (other kinds cannot be scaled)
	// (PATCH /api/workloads/{kind}/{ns}/{name}/scale)
	ScaleWorkload(w http.ResponseWriter, r *http.Request, kind ScaleWorkloadParamsKind, ns NamespaceParam, name NameParam)
}

